package com.shazwan.idash.a1lab.target;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.media.*;import android.view.*;import android.widget.*;import java.lang.ref.WeakReference;import java.util.concurrent.atomic.AtomicInteger;
/** Self-written probe, never presented as BitChord. No network, accounts or external music. */
public final class ProbeActivity extends Activity {
 static volatile WeakReference<ProbeActivity> current=new WeakReference<>(null);static final AtomicInteger count=new AtomicInteger();static volatile String lastInput="";static volatile int display=-1,width,height;static volatile boolean focused,playing;String section="Library";LinearLayout content;TextView info;EditText search;AlertDialog popup;AudioManager audio;AudioFocusRequest focusRequest;ToneGenerator tone;
 @Override public void onCreate(Bundle state){super.onCreate(state);current=new WeakReference<>(this);display=getWindowManager().getDefaultDisplay().getDisplayId();audio=(AudioManager)getSystemService(AUDIO_SERVICE);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(8),dp(4),dp(8),dp(4));root.setBackgroundColor(0xff24374c);info=label("",13);root.addView(info);LinearLayout nav=new LinearLayout(this);for(String s:new String[]{"Library","Search","Now Playing","Settings"})nav.addView(button(s,()->{section=s;render();}),new LinearLayout.LayoutParams(0,dp(48),1));root.addView(nav);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{width=r-l;height=b-t;display=getWindowManager().getDefaultDisplay().getDisplayId();updateInfo();});setContentView(root);render();}
 int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}TextView label(String value,int sp){TextView t=new TextView(this);t.setText(value);t.setTextSize(sp);t.setTextColor(Color.WHITE);return t;}Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setTextSize(12);b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());return b;}
 void updateInfo(){info.setText("OWN PROBE · UID "+android.os.Process.myUid()+" · display "+display+" · "+width+"×"+height);}
 void render(){content.removeAllViews();content.addView(label(section+" · not BitChord",18));content.addView(button("Touch counter: "+count.get(),()->{count.incrementAndGet();render();}));search=new EditText(this);search.setSingleLine(true);search.setHint("Probe text input");search.setText(lastInput);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){lastInput=s.toString();}public void afterTextChanged(android.text.Editable e){}});content.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));content.addView(button("Popup",()->{popup=new AlertDialog.Builder(this).setTitle("Own target dialog").setMessage("This dialog belongs to the probe, not BitChord.").setPositiveButton("OK",(d,w)->count.incrementAndGet()).show();}));content.addView(button(playing?"Pause test tone":"Play test tone",()->{if(playing)stopAudio();else playTone();render();}));content.addView(label("Back returns to Library. Host Stop closes this owned Activity. No music playback certification.",12));updateInfo();}
 void playTone(){focusRequest=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change<0){stopAudio();render();}}).build();if(audio.requestAudioFocus(focusRequest)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED){playing=true;tone=new ToneGenerator(AudioManager.STREAM_MUSIC,10);tone.startTone(ToneGenerator.TONE_PROP_BEEP,300);}}
 void stopAudio(){playing=false;if(tone!=null){tone.release();tone=null;}if(focusRequest!=null){audio.abandonAudioFocusRequest(focusRequest);focusRequest=null;}}
 @Override public void onWindowFocusChanged(boolean has){super.onWindowFocusChanged(has);focused=has;}@Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);updateInfo();}@Override public void onBackPressed(){if(popup!=null&&popup.isShowing()){popup.dismiss();return;}section="Library";render();}
 @Override protected void onResume(){super.onResume();current=new WeakReference<>(this);display=getWindowManager().getDefaultDisplay().getDisplayId();}@Override protected void onStop(){stopAudio();super.onStop();}@Override protected void onDestroy(){stopAudio();if(popup!=null)popup.dismiss();if(current.get()==this){current=new WeakReference<>(null);display=-1;}super.onDestroy();}
 void hostedTouch(MotionEvent event){if(popup!=null&&popup.isShowing()){View decor=popup.getWindow().getDecorView();int[] at=new int[2];decor.getLocationOnScreen(at);event.offsetLocation(-at[0],-at[1]);popup.dispatchTouchEvent(event);}else dispatchTouchEvent(event);}
}
